let wizardTab='Overview',rosterTag='',announcedMoment='',s=null,route=null,modalEpoch=0,busy=false,lastTick=performance.now(),localAt=0,cloudAt=0,lastRail=0,toastTimer,archivePage=null,historyWizard=null,watch={id:null,index:0,playing:false,at:0},inventory={family:'',rarity:'',slot:'',owner:'',sort:'power',search:'',page:0},recordFilters={metric:'depth',status:'All-Time'},archiveType='wizards',archiveCursor='',leagueView=0,authMode='login';
const $=id=>document.getElementById(id),n=x=>Math.floor(x||0).toLocaleString(),fmt=x=>Number(x||0).toLocaleString(undefined,{maximumFractionDigits:1}),duration=x=>x<60000?`${Math.ceil(Math.max(0,x)/1000)}s`:x<HOUR?`${Math.ceil(x/60000)}m`:`${(x/HOUR).toFixed(1)}h`,family=id=>FAMILIES.find(f=>f.id===id),button=(label,action,data='',cls='')=>`<button class="${cls}" data-act="${action}" ${data}>${label}</button>`,metric=(label,value)=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`,empty=t=>`<div class="empty">${t}</div>`,section=t=>`<div class="section-title"><h3>${t}</h3></div>`,options=(rows,value)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join(''),tag=t=>`<span class="tag">${esc(t)}</span>`;
function toast(t){sound('notice');$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function errorMessage(e){const code=e.code||'';if(code.includes('invalid-credential'))return 'Email or password was not recognized.';if(code.includes('email-already-in-use'))return 'That email already has an account. Choose Sign in.';if(code.includes('weak-password'))return 'Use a password of at least six characters.';if(code.includes('operation-not-allowed'))return 'Enable Email/Password in Firebase Authentication, then try again.';if(code.includes('permission-denied'))return 'Firestore denied access. Publish the included firestore.rules in your Firebase console.';if(code.includes('unauthorized-domain'))return 'Add your GitHub Pages domain to Firebase Authentication → Settings → Authorized domains.';return e.message||'Something went wrong. Your last saved progress is safe.';}
async function checkpoint(cloud=false){if(!s)return;updateTutorial(s);try{await P.saveLocal(s);if(cloud&&P.account!=='local')await P.saveCloud(s);}catch(e){toast(errorMessage(e));}updateHUD();}
function authScreen(){s=null;route=null;$('panel').close();$('app').innerHTML=`<main class="auth-page"><section class="auth-art"><span class="crest">✦</span><div class="eyebrow">A generational academy management game</div><h1>Small beginnings.<br>Extraordinary<br>histories.</h1><p>Five beds. A questionable dungeon. An institution that will outlive everyone who builds it.</p><div class="mini-castle">${castleArt()}</div><p class="fineprint" style="margin-top:24px">WIZARD ACADEMY &nbsp; / &nbsp; ${VERSION}</p></section><section class="auth-card-wrap"><div class="auth-card"><div class="eyebrow" style="color:#a88c56">The headmaster’s office</div><h2>${authMode==='signup'?'Begin your legacy':'Welcome, Headmaster.'}</h2><p class="muted">${authMode==='signup'?'Your academy starts with a name.':'Your institution is waiting for you.'}</p><form id="auth-form"><label>Email address<input id="email" type="email" autocomplete="email" required placeholder="headmaster@academy.edu"></label><label>Password<input id="password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="6" required placeholder="At least six characters"></label><button type="submit">${authMode==='signup'?'Create account':'Sign in'} <span aria-hidden="true">→</span></button></form>${button(authMode==='signup'?'Already enrolled? Sign in':'New here? Create an account','auth-toggle','','secondary')}${button('Install Wizard Academy','install-help','','secondary')}${button('Forgot password?','reset-password','','secondary')}${button('Play locally on this device','local','','secondary')}<p class="fineprint" style="margin-top:15px">Cloud accounts save across devices. Local play stays in this browser; export backups from the Front Desk.</p><p id="auth-status" class="auth-status" role="alert"></p></div></section></main>`;}
function foundScreen(){route=null;$('app').innerHTML=`<main class="auth-page"><section class="auth-art"><div class="eyebrow">An institution in the making</div><h1>What will they<br>remember?</h1><p>Not every wizard will be a legend. Every wizard will have a story.</p><div class="mini-castle">${castleArt()}</div></section><section class="auth-card-wrap"><div class="auth-card"><h2>Found your academy</h2><p class="muted">An empty building. Five beds. Your first generation has not yet arrived.</p><form id="found-form"><label>Academy name<input id="academy-name" maxlength="48" required placeholder="The Wayward Academy" value="The Wayward Academy"></label><button>Sign the founding charter</button></form><div class="note">One real day is one Academy Year. Up to twelve hours of idle progress await your return. Unknown dungeon floors always require your decision.</div><p class="fineprint">${P.account==='local'?'Local academy · saved in this browser':'Cloud academy · saved to your account'}</p></div></section></main>`;}
async function enterAccount(id){if(!await P.lockAccount(id))throw Error('This academy is already open in another tab. Close that tab, then try again.');s=await P.load(id);localStorage.setItem('wa-mode',id==='local'?'local':'cloud');if(!s){foundScreen();return;}if(s.schema!==1)throw Error('Unsupported save schema. Update the game files.');if(s.combat&&!COMBAT_SPEEDS.includes(s.combat.speed))s.combat.speed=1;const report=T.processTime(s);updateTutorial(s);ensureJerseys(s);leagueView=L.playerSchool(s).league;renderMain();await checkpoint();if(report.elapsed>120000)showReport(report);}
function renderMain(){if(!s)return;const yr=M.year(s),frac=s.time%DAY/DAY,open=s.intro,chat=s.chat[0];$('app').innerHTML=`<header class="topbar"><div class="brand"><span class="crest" aria-hidden="true">✦</span><div><div class="eyebrow">Wizard Academy</div><h1>${esc(s.name)}</h1></div></div><div class="resources" id="resources"></div>${button(audioSettings(s).enabled?'♫ Sound on':'♫ Muted','sound-toggle','id="sound-toggle" aria-label="Toggle game sound"','sound-toggle')}</header><div id="rift-spotlight" class="rift-spotlight"></div><div class="layout"><main class="main-school"><div class="school-heading"><div><h2>The academy grounds</h2><p>${s.prestige<25?'A little rough around the edges. Just like its students.':s.prestige<100?'The walls are growing. So is the legend.':'Built by generations. Remembered for centuries.'}</p></div><div class="year-chip" id="year-chip">YEAR ${yr}<span>${['Early','Mid','Late'][Math.min(2,Math.floor(frac*3))]} term</span></div></div>${!open?`<div class="onboarding-banner"><h3>The keys are yours.</h3><p>Your charter is signed. Open the front desk, dormitory, storage, archives, and dungeon entrance to receive your first applicants.</p>${button('Open the academy','open-foundation','','gold')}</div>`:M.active(s).length===0?`<div class="onboarding-banner"><h3>${s.stats.recruited?'The academy can begin again.':'The founding generation is waiting.'}</h3><p>Tap the Front Desk to recruit your first wizards. Open the Practice Hall, Rune Chamber, and Arcane Rift when you are ready.</p>${button('Meet the applicants','room','data-room="desk"','gold')}</div>`:''}<div id="tutorial-banner"></div><div id="highlights-strip"></div><div class="school-scene"><div class="room-grid">${ROOMS.map(r=>{const lv=s.rooms[r.id];return `<button class="room ${lv?'':'locked'}" data-act="room" data-room="${r.id}" aria-label="${esc(r.name)} — ${esc(r.sub)}${lv?'':', unopened'}">${lv?roomArt(r.id,lv):`<div class="blueprint"><div>${r.icon}<small>${lv?'':s.prestige<r.prestige?r.prestige+' Prestige':'Room for possibility'}</small></div></div>`}<span class="room-label">${esc(r.name)}<b>${lv?'ⅠⅡⅢⅣⅤⅥ'[lv-1]:'＋'}</b></span>${r.id==='desk'&&s.applicants.length?`<span class="room-badge">${s.applicants.length}</span>`:r.id==='gate'&&s.expedition?'<span class="room-badge">!</span>':''}</button>`;}).join('')}</div><canvas class="scene-canvas" aria-hidden="true"></canvas><div class="walkway">The institution remains</div></div><div class="scene-hint"><span>Tap a room to manage it · Every wizard has a story</span><span id="save-status">${esc(P.cloudStatus)}</span></div><div class="bottom-progress"><span class="symbol">◈</span><p><strong id="depth-line">${s.depth?'Deepest descent · Floor '+s.depth:'Belowstairs awaits'}</strong><br>${s.expedition?'An expedition is outside. Tap the dungeon gate to return to it.':'The next floor is always your decision. Nobody advances without you.'}</p></div></main><aside class="side-rail" id="rail"></aside></div>`;updateHUD();renderRail();}
function updateHUD(){updateHighlights();updateTutorialBanner();if($('sound-toggle')&&s)$('sound-toggle').textContent=audioSettings(s).enabled?'♫ Sound on':'♫ Muted';updateRiftSpotlight();if(!s||!$('resources'))return;$('resources').innerHTML=[['Gold','◌ '+n(s.gold)],['Prestige','✦ '+fmt(s.prestige)],['Wizards',M.active(s).length+' / '+M.capacity(s)],['Boss seals','◈ '+n(s.seals)]].map(([k,v])=>`<div class="resource"><span>${k}</span><strong>${v}</strong></div>`).join('');$('save-status').textContent=P.cloudStatus;$('year-chip').innerHTML=`YEAR ${M.year(s)}<span>${['Early','Mid','Late'][Math.floor((s.time%DAY/DAY)*3)]} term</span>`;}
function updateRiftSpotlight(){const el=$('rift-spotlight');if(!el||!s?.league)return;const league=L.playerSchool(s).league,record=s.league.tables.player,rank=L.standings(s,league).findIndex(t=>t.id==='player')+1,next=L.nextFixture(s),remaining=Math.max(0,(next.at-s.time-Math.min(5000,Math.max(0,Date.now()-s.lastWall)))/1000);const key=[s.league.year,record.w,record.l,rank,league,next.label,Math.ceil(remaining),s.league.lastMatch?.id].join('|');if(el.dataset?.key===key)return;if(el.dataset)el.dataset.key=key;el.innerHTML=`<button class="rift-summary" data-act="room" data-room="rift"><span class="rift-emblem">◈</span><span><small>ARCANE RIFT · SEASON ${s.league.year}</small><strong>${record.w}–${record.l} <em>· #${rank} ${esc(LEAGUES[league])}</em></strong></span><span class="rift-next"><small>${esc(next.stage||'Next match')} · ${taskTime(remaining)}</small><strong>${esc(next.label)}</strong></span></button>${s.league.lastMatch?button('▶ Watch latest','watch-last','','rift-watch'):''}`;}
function updateTutorialBanner(){if(!s)return;const el=$('tutorial-banner');if(!el)return;const q=s.tutorial,m=currentMission(s),key=JSON.stringify([q?.hidden,q?.done,q?.claimed,s.intro]);if(el.dataset?.key===key)return;if(el.dataset)el.dataset.key=key;el.innerHTML=q?.hidden||!m?'':`<div class="tutorial-banner"><div><small>HEADMASTER’S FIRST CHARTER · ${MISSIONS.indexOf(m)+1}/${MISSIONS.length}</small><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p></div><div class="actions">${q?.done.includes(m.id)?button('Claim '+m.gold+' gold','tutorial-claim',`data-id="${m.id}"`):button(s.intro?'Take me there':'Open the academy',s.intro?'tutorial-go':'open-foundation',`data-id="${m.id}"`)}${button('Mission journal','tutorial','','secondary')}${button('Hide guide','tutorial-hide','','secondary small')}</div></div>`;for(const room of document.querySelectorAll?.('.room')||[])room.classList?.toggle?.('tutorial-target',!q?.hidden&&!!m&&room.dataset.room===m.room&&!q?.done.includes(m.id));}
function renderTutorial(){const q=updateTutorial(s),current=currentMission(s);const cards=list=>list.map(m=>{const claimed=q.claimed.includes(m.id),done=q.done.includes(m.id),claimable=done&&!claimed&&(SIDE_MISSIONS.includes(m)||current?.id===m.id);return `<article class="card"><small>${claimed?'✓ COMPLETED':done?'✓ OBJECTIVE MET':current?.id===m.id?'CURRENT MISSION':'MISSION'}</small><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><p class="fineprint">One-time reward: ${m.gold} gold</p><div class="actions">${claimable?button('Claim reward','tutorial-claim',`data-id="${m.id}"`):''}${!claimed?button('Visit '+(ROOMS.find(r=>r.id===m.room)?.name||'room'),'tutorial-go',`data-id="${m.id}"`,'secondary'):''}</div></article>`;}).join('');panel('The first charter','Learn by running your academy',`<p class="panel-intro">${q.claimed.filter(id=>MISSIONS.some(m=>m.id===id)).length} / ${MISSIONS.length} core missions complete. Progress is remembered across visits. You can explore freely and finish objectives early.</p>${button(q.hidden?'Show guide on grounds':'Hide guide on grounds','tutorial-hide','','secondary')}<div class="cards" style="margin-top:16px">${cards(MISSIONS)}</div>${section('Your next adventures · optional')}<div class="cards">${cards(SIDE_MISSIONS)}</div><div class="note">The institution is yours. New floors require your decision; production and scheduled sport continue for up to 12 hours away. Check the Front Desk handbook whenever you need a reminder.</div>`);}
function emergencyAdmissions(){const missing=Math.max(0,5-M.active(s).length);return s.intro&&missing?`<div class="note emergency-admissions"><strong>Short-handed? Rebuild now.</strong><p>Recruit ${missing} basic level-1 wizard${missing===1?'':'s'} instantly, free. Modest natural stats, no equipment or Prestige bonuses. Restores five active wizards and fills vacant Rift lineup slots.</p>${button('Emergency recruit '+missing+' · Free','emergency-recruit')}<small>Past forfeits remain recorded. Injured and expedition-bound wizards still count as active.</small></div>`:'';}
function soundControls(){const a=audioSettings(s);return `<p class="fineprint">Sound starts after a tap. Settings apply on this account. Audio pauses when the page is hidden.</p><label>Sound<select data-change="audio-enabled">${options([['yes','On'],['no','Muted']],a.enabled?'yes':'no')}</select></label><div class="sound-controls">${[['master','Master volume'],['effects','Effects & notifications'],['ambience','Room ambience'],['music','Gentle academy music']].map(([key,label])=>`<label>${label}<input type="range" min="0" max="100" step="1" value="${Math.round(a[key]*100)}" data-audio="${key}" aria-label="${label}"></label>`).join('')}</div>${button('Preview magic','sound-preview','','secondary')}`;}
function renderRail(){if(!s||!$('rail'))return;const chat=s.chat[0],fixture=L.nextFixture(s),pending=s.events[0];$('rail').innerHTML=`<section><div class="rail-title">The noticeboard <span>Office dispatch</span></div><div class="notice"><div class="eyebrow" style="font-size:8px">${pending?'A decision awaits':'Your next chapter'}</div><h4>${pending?esc(pending.title):s.stats.recruited<5?'Five beds. Five beginnings.':s.depth===0?'A door beneath the school.':!s.rooms.runes?'A little magical industry.':'The academy is in motion.'}</h4><p>${pending?esc(pending.body):s.stats.recruited<5?'Your founding generation is waiting at Admissions. Choose who gets the first key.':s.depth===0?'Choose up to three wizards at Belowstairs. Their first expedition will be remembered.':!s.rooms.runes?'Open the Rune Chamber. Equipment is powerful; somebody must keep it supplied.':'Train, produce, prepare. Tomorrow’s legends are today’s difficult students.'}</p>${button(pending?'Review the matter →':s.stats.recruited<5?'Visit Admissions →':s.depth===0?'Visit Belowstairs →':'Visit Front Desk →',pending?'events':'room',pending?'':`data-room="${s.stats.recruited<5?'desk':s.depth===0?'gate':'desk'}"`)}</div></section><section><div class="rail-title">Overheard <span>In the corridors</span></div><div class="conversation">“${esc(chat?.text||'Do we actually have permission to open an academy here?')}”</div><div class="speaker">${esc(chat?.name||'The admissions clerk')}${chat?.to?' · to '+esc(chat.to):''}</div></section><section><div class="rail-title">Academy chronicle <span>Year ${M.year(s)}</span></div><div class="rail-feed">${s.feed.slice(0,4).map(e=>`<div class="feed-item"><div class="date">YEAR ${e.year} / ${esc(e.kind.toUpperCase())}</div><p>${esc(e.text)}</p></div>`).join('')}</div></section><div class="sidebar-footer">${esc(LEAGUES[L.playerSchool(s).league])} · Next: ${esc(fixture.label)}<br>In ${duration(fixture.at-s.time)} · 24 hours per Academy Year<br><span class="fineprint">Wizard Academy ${VERSION} · The first charter</span></div>`;}
function panel(title,sub,content){const existingPitch=route?.type==='match'?$('rift-live-pitch'):null;const dlg=$('panel'),existingCanvas=['combat','duel'].includes(route?.type)?$('combat-canvas'):null;$('panel-head').innerHTML=`<div><div class="eyebrow">${esc(sub)}</div><h2>${esc(title)}</h2></div>${button('×','close','aria-label="Close panel"')}`;$('panel-body').innerHTML=`<div class="tab-content${route?.type==='combat'?' combat-content':''}${content.includes('data-task=')||content.includes('data-production=')?' task-content':''}${route?.type==='match'?' match-content':''}">${content}</div>`;if(existingCanvas&&existingCanvas.tagName==='CANVAS'){const replacement=$('panel-body').querySelector('#combat-canvas');if(replacement)replacement.replaceWith(existingCanvas);}if(existingPitch?.tagName==='DIV'&&existingPitch.dataset.match===route?.match?.id){const next=$('panel-body').querySelector('#rift-live-pitch');if(next)next.replaceWith(existingPitch);}if(!dlg.open)dlg.showModal();}
function tabs(items,selected){return `<div class="tabs">${items.map(([id,label])=>button(label,'tab',`data-tab="${id}"`,selected===id?'active':'')).join('')}</div>`;}
function openRoom(id,tab){sound('room',{room:id});historyWizard=null;archivePage=null;archiveCursor='';route={type:'room',id,tab:tab||({desk:'applicants',dorm:'roster',storage:'items',rift:'league',archives:'records',hall:'legends'}[id]||'main')};renderPanel();}
function wizardLabels(w){return (w.tags||[]).map(t=>`<span class="tag wizard-label">${esc(t)}</span>`).join('');}
function rosterCard(w){const a=M.attributes(s,w);return `<article class="card roster-card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>Age ${M.age(s,w)} · ${esc(w.status)} · Lv ${w.level} / Rift ${w.sportLevel}</p></div></div><div class="chips">${wizardLabels(w)||'<small>No tags yet</small>'}</div><p class="roster-job">${s.expedition?.ids.includes(w.id)?'On expedition':w.injury?'✚ '+esc(w.injury.name):esc(JOBS[w.job]||w.job)}</p><div class="roster-gear">${SLOTS.map(slot=>{const item=s.items.find(i=>i.id===w.equipment[slot]);return `<button class="secondary" data-act="${w.status==='Active'?'equipment-slot':'wizard'}" data-id="${w.id}" data-slot="${slot}"><small>${slot.toUpperCase()}</small><strong>${item?family(item.family).icon+' '+esc(item.name):'Empty'}</strong></button>`;}).join('')}</div><div class="vitals"><span>${Math.round(w.hp||0)} / ${a.hp} HP</span><span>${Math.round(w.mana||0)} / ${a.mana} mana</span></div><div class="actions">${button('Profile & tags','wizard',`data-id="${w.id}"`,'secondary')}</div>${w.status==='Active'?`<details class="roster-work"><summary>Work progress</summary>${taskMarkup(w)}</details>`:''}</article>`;}
function tagEditor(w){return `<section class="profile-tags"><h3>Headmaster’s tags</h3><p class="fineprint">Your labels for remembering a wizard’s role. They do not change jobs, builds, or Rift eligibility. Up to six tags.</p><div class="chips">${(w.tags||[]).map(t=>button(esc(t)+' ×','tag-remove',`data-id="${w.id}" data-label="${esc(t)}" aria-label="Remove ${esc(t)} tag"`,'secondary small')).join('')||'<small>No tags assigned.</small>'}</div><div class="chips">${TAGS.filter(t=>!(w.tags||[]).some(x=>x.toLowerCase()===t.toLowerCase())).map(t=>button('+ '+t,'tag-add',`data-id="${w.id}" data-label="${t}"`,'secondary small')).join('')}</div><div class="custom-tag"><label>Custom tag<input id="wizard-custom-tag" maxlength="24" placeholder="e.g. Boss team"></label>${button('Add tag','tag-custom',`data-id="${w.id}"`,'secondary')}</div></section>`;}
function wizardCard(w,applicant=false){if(!applicant)return rosterCard(w);const a=M.attributes(s,w);return `<article class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>Age ${M.age(s,w)} · ${applicant?'Applicant':esc(w.status)+' · Level '+w.level}</p></div></div><div class="chips">${w.founder?'<span class="tag founder">Founding generation</span>':''}${w.emergency?tag('Emergency recruit · Basic'):''}${tag(TRAITS[w.trait][0])}${tag('Rift potential '+w.potential)}${w.hof?tag('Hall of Fame'):''}</div><p>${esc(TRAITS[w.trait][1])}</p><div class="metrics">${metric('Health',a.hp)}${metric('Mana',a.mana)}${metric('Power',a.power)}${metric('Rift LV',w.sportLevel)}</div>${!applicant&&w.status==='Active'?taskMarkup(w):''}${applicant?`<p class="fineprint">Application held for ${duration(w.expires-s.time)}. No recruitment fee.</p><div class="actions">${button('Offer a place','recruit',`data-id="${w.id}" ${M.active(s).length>=M.capacity(s)?'disabled':''}`)}${button('View profile','wizard',`data-id="${w.id}"`,'secondary')}</div>`:`<p>${w.injury?'✚ '+esc(w.injury.name):esc(JOBS[w.job]||w.job)} ${s.expedition?.ids.includes(w.id)?'· On expedition':''}</p><div class="bar"><i style="width:${Math.max(0,Math.min(100,w.hp/a.hp*100))}%"></i></div><div class="vitals"><span>${Math.round(w.hp||0)} / ${a.hp} HP</span><span>${Math.round(w.mana||0)} / ${a.mana} mana</span></div><div class="actions">${button('Meet '+esc(w.name.split(' ')[0]),'wizard',`data-id="${w.id}"`,'secondary')}</div>`}</article>`;}
function facilityHeader(id){const r=ROOMS.find(r=>r.id===id),lv=s.rooms[id],cost=lv?Math.round((r.cost||140)*Math.pow(2.15,lv)):r.cost,req=r.prestige+lv*8;return `<div class="note"><strong>${lv?'Tier '+lv+' facility':'Unopened wing'}</strong> · ${lv>=6?'Architectural potential fulfilled.':`${n(cost)} gold · ${req} Prestige required`}<div class="actions" style="margin-top:10px">${lv<6?button(lv?'Expand facility':'Open this room','upgrade',`data-id="${id}" ${s.gold<cost||s.prestige<req?'disabled':''}`):''}</div></div>`;}
function facultyPanel(id){if(!['training','runes','infirmary','rift','garden','observatory','archives'].includes(id))return '';const retirees=s.wizards.filter(w=>['Retired','Faculty'].includes(w.status));const current=s.wizards.find(w=>w.id===s.faculty[id]);return `${section('The professor’s desk')}<p class="panel-intro">One faculty member per facility. Bonuses reflect their lived career. Professors eventually pass away; their record never does.</p><label>Appoint faculty<select data-change="faculty" data-room="${id}">${options([['','No professor assigned'],...retirees.map(w=>[w.id,w.name+' · age '+M.age(s,w)])],s.faculty[id]||'')}</select></label>${current?`<div class="note">${esc(current.name)} · +${Math.round((M.bonus(s,id)-1)*100)}% effectiveness. ${button('View career','wizard',`data-id="${current.id}"`,'secondary small')}</div>`:''}`;}
function taskMarkup(w){const t=taskStatus(s,w);return `<div class="task-progress" data-task="${w.id}"><div class="task-heading"><strong data-task-label>${esc(t.label)}</strong><span data-task-time>${t.blocked?'Waiting':t.remaining===null?'':t.remaining<=0?(w.job==='rest'||w.job==='recovery'?'Ready':'Completing…'):taskTime(t.remaining)+' remaining'}</span></div><div class="task-track" role="progressbar" aria-label="${esc(t.label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(t.fraction*100)}"><i style="width:${t.fraction*100}%"></i></div><p data-task-detail>${esc(t.detail)}</p><small data-task-cycle>${t.cycle?'Each cycle: '+taskTime(t.cycle)+' · repeats automatically':''}</small></div>`;}
function updateTaskViews(){for(const el of document.querySelectorAll('[data-task]')){const w=s.wizards.find(w=>w.id===el.dataset.task);if(!w)continue;const t=taskStatus(s,w,Math.max(0,Date.now()-s.lastWall)/1000),percent=Math.max(0,Math.min(100,t.fraction*100));el.classList.toggle('waiting',t.blocked);el.querySelector('[data-task-label]').textContent=t.label;el.querySelector('[data-task-time]').textContent=t.blocked?'Waiting':t.remaining===null?'':t.remaining<=0?(w.job==='rest'||w.job==='recovery'?'Ready':'Completing…'):taskTime(t.remaining)+' remaining';el.querySelector('.task-track i').style.width=percent+'%';el.querySelector('.task-track').setAttribute('aria-valuenow',String(Math.round(percent)));el.querySelector('[data-task-detail]').textContent=t.detail;el.querySelector('[data-task-cycle]').textContent=t.cycle?'Each cycle: '+taskTime(t.cycle)+' · repeats automatically':'';}}
function workerButton(job,label,tier=1){return button(label||'Assign wizards','workers',`data-job="${job}" data-tier="${tier}"`,'secondary small');}
function productionMarkup(g){return `<article class="production-card" data-production="${g.key}" data-job="${g.job}" data-tier="${g.tier}"><div class="task-heading"><strong>${esc(g.label)}</strong>${workerButton(g.job,'Manage wizards',g.tier)}</div><p data-production-team>${esc(g.team.map(w=>w.name).join(', '))}</p><div class="task-track" role="progressbar" aria-label="${esc(g.label)} shared progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(g.fraction*100)}"><i style="width:${g.fraction*100}%"></i></div><p data-production-time>${g.blocked?esc(g.detail):taskTime(g.remaining)+' until next batch'}</p><small data-production-rate>${g.workers.length} working · ${g.cycle?'one batch every '+taskTime(g.cycle):'paused'}</small><p class="fineprint">${esc(g.output)}</p></article>`;}
function updateProductionViews(){for(const el of document.querySelectorAll('[data-production]')){const g=productionStatus(s,el.dataset.job,Number(el.dataset.tier),Math.max(0,Date.now()-s.lastWall)/1000);el.classList.toggle('waiting',g.blocked);el.querySelector('.task-track i').style.width=g.fraction*100+'%';el.querySelector('.task-track').setAttribute('aria-valuenow',String(Math.round(g.fraction*100)));el.querySelector('[data-production-team]').textContent=g.team.map(w=>w.name+(s.expedition?.ids.includes(w.id)?' (away)':'')).join(', ');el.querySelector('[data-production-time]').textContent=g.blocked?g.detail:g.remaining<=0?'Completing batch…':taskTime(g.remaining)+' until next batch';el.querySelector('[data-production-rate]').textContent=g.workers.length+' working · '+(g.cycle?'one batch every '+taskTime(g.cycle):'paused');}}
function assignmentPanel(jobs){const production=jobs.filter(j=>PRODUCTION_JOBS.includes(j)),individual=jobs.filter(j=>!PRODUCTION_JOBS.includes(j)),ws=M.active(s).filter(w=>individual.includes(w.job));return `<div class="actions">${jobs.map(j=>workerButton(j,JOBS[j])).join('')}</div>${productionGroups(s,production).map(productionMarkup).join('')}${ws.map(w=>`<div class="assignment-row"><strong>${esc(w.name)}</strong>${taskMarkup(w)}</div>`).join('')}${!ws.length&&!productionGroups(s,production).length?'<p class="fineprint">No wizards assigned here. Choose a task above to select workers.</p>':''}`;}
function renderWorkers(){const {job,tier}=route,f=family(job);let html=`<p class="panel-intro">Select the wizards for this task. Their current assignments are shown below. Applying moves selected wizards here; deselected workers rest. Other work stays assigned.</p>${f?`<div class="tabs">${[1,2,3].map(t=>button('Tier '+t,'worker-tier',`data-tier="${t}"`,t===tier?'active':'')).join('')}</div><p class="fineprint">Tier II requires level 10; Tier III requires level 25. Each tier has its own shared batch.</p>`:''}<div class="worker-picker">${M.active(s).map(w=>{const reason=workerReason(s,w,job,tier),selected=route.selected.includes(w.id);return `<label class="worker-choice"><input type="checkbox" data-change="worker-select" data-id="${w.id}" ${selected?'checked':''} ${reason?'disabled':''}><span><strong>${esc(w.name)} · Level ${w.level}</strong><small>${esc(JOBS[w.job]||w.job)}${family(w.job)?' · Tier '+productionTier(w):''}${reason?' · '+esc(reason):''}</small></span></label>`;}).join('')||empty('Recruit wizards in Admissions first.')}</div><div class="actions">${button('Apply assignment','workers-apply')}${button('Back to room','workers-back','','secondary')}</div>`;panel((JOBS[job]||job)+(f?' · Tier '+tier:''),'Choose your wizards',html);}

function renderPanel(){if(!route||!s)return;modalEpoch++;if(route.type==='equipment-slot'){renderEquipmentSlot();return;}if(route.type==='install'){renderInstall();return;}if(route.type==='highlights'){renderHighlights();return;}if(route.type==='duel'){renderDuel();return;}if(route.type==='tutorial'){renderTutorial();return;}if(route.type==='workers'){renderWorkers();return;}if(route.type==='wizard'){renderWizard();return;}if(route.type==='forest'){renderForest();return;}if(route.type==='rival'){renderRival();return;}if(route.type==='item'){renderItem();return;}if(route.type==='combat'){renderCombat();return;}if(route.type==='events'){renderEvents();return;}if(route.type==='match'){renderMatch();return;}if(route.type==='season'){renderSeason();return;}const id=route.id,r=ROOMS.find(r=>r.id===id),tab=route.tab;let html='';if(!s.rooms[id]){panel(r.name,r.sub,`<p class="panel-intro">${{training:'A place to aim spells at things that have consented.',runes:'The quiet industry behind spectacular magic. Unscribed stones become twelve charges of a chosen rune.',rift:'Two Strikers. One Controller. Two Wardens. An entire league to annoy.',infirmary:'The bed linen is clean. The prognosis is occasionally sarcastic.',hall:'Build a home for the names that define your academy.',garden:'Potion ingredients grow best when nobody makes eye contact.',observatory:'Trade runestones and patient work for lasting Prestige.'}[id]||'The academy begins with one decision.'}</p>${facilityHeader(id)}`);return;}
 if(id==='desk'){html=tabs([['applicants','Admissions'],['office','Office'],['events','Decisions'],['settings','Settings & save'],['guide','Headmaster’s handbook']],tab);if(tab==='applicants')html+=emergencyAdmissions()+`<p class="panel-intro">A new pool arrives every Academy Year. Applications remain for three years. Prestige attracts more promising candidates.</p><div class="metrics">${metric('Available beds',M.capacity(s)-M.active(s).length)}${metric('Applicants',s.applicants.length)}${metric('Next intake',duration(DAY-s.time%DAY))}${metric('Prestige',fmt(s.prestige))}</div><div class="cards">${s.applicants.map(w=>wizardCard(w,true)).join('')||empty('The next applicants will arrive with the new Academy Year.')}</div>`;
 else if(tab==='office')html+=`<div class="metrics">${metric('Year',M.year(s))}${metric('Gold',n(s.gold))}${metric('Prestige',fmt(s.prestige))}${metric('Deepest floor',s.depth)}</div>${section('Academy wings')}<div class="cards">${ROOMS.map(r=>`<div class="card"><h3>${esc(r.name)}</h3><p>${esc(r.sub)}</p>${facilityHeader(r.id)}</div>`).join('')}</div>${section('Academy reputation')}<div class="metrics">${Object.entries(s.reputation||{}).map(([k,v])=>metric(k,fmt(v))).join('')}</div>${section('Rival institutions')}<div class="cards">${(s.rivalHistory||[]).slice(0,5).map(e=>`<div class="card"><strong>${esc(e.name)}</strong><p>Year ${e.year} · ${esc(e.text)}</p></div>`).join('')||empty('Rival stories unfold as Academy Years pass.')}</div>${s.league?`<details><summary>All rival academies</summary><div class="cards">${s.league.schools.filter(x=>x.id!=='player').map(x=>`<div class="card"><h3>${esc(x.name)}</h3><p>${esc(LEAGUES[x.league])} · ${esc(x.personality||'')}</p>${button('Institution profile','rival-open',`data-id="${x.id}"`,'secondary')}</div>`).join('')}</div></details>`:''}${section('Clerical work')}<p class="panel-intro">Earn a little gold by turning magical disasters into orderly files. No resource cost.</p>${assignmentPanel(['clerical'])}`;
 else if(tab==='events')html+=eventContent();
 else if(tab==='settings')html+=`<div class="note"><strong>${esc(P.cloudStatus)}</strong><br>${P.account==='local'?'This academy is stored on this browser only. Export backups before clearing browser data.':'Cloud sync uses your private UID. Saves synchronize about once a minute and on key decisions. Keep one device active at a time.'}</div><div class="actions">${button('Save now','save')}${button('Export complete backup','export','','secondary')}${button('Previous device snapshot','device-recovery','','secondary')}${button('Sign out','logout','','secondary')}</div>${P.conflicted?`<div class="note warning">Another device has newer progress. Export this session if needed, then reload. ${button('Reload cloud save','reload','','secondary')}</div>`:''}${section('Sound & music')}${soundControls()}${section('Presentation')}<label>Academy & combat motion<select data-change="motion">${options([['yes','Living academy'],['no','Reduced motion']],s.settings.motion?'yes':'no')}</select></label>${P.account==='local'?`${section('Restore a local backup')}<p class="panel-intro">This replaces the local academy. Export it first if you want to keep it. Cloud saves are not overwritten.</p><label>Choose a Wizard Academy JSON backup<input id="import-file" type="file" accept="application/json,.json"></label>${button('Restore selected backup','import','','danger')}`:''}${section('Install Wizard Academy')}${button('Install & app updates','install-help','','secondary')}${section('Build information')}<p class="fineprint">Wizard Academy ${VERSION} · Save schema ${s.schema} · Cloud revision ${s.revision}<br>No runtime AI, no build step, no service-account credentials.<br>Clock progress is capped at 12 hours per return. For a longer absence, production, aging, and league schedules pause beyond that cap.</p>`;
 else html+=guide();}
 else if(id==='dorm'){html=`<p class="panel-intro">${M.active(s).length} active wizards · ${M.capacity(s)} beds. Equipment defines a build; nobody is born into a class.</p><label>Filter by tag<select data-change="roster-tag">${options([['','All wizards'],...Array.from(new Set(s.wizards.flatMap(w=>w.tags||[]))).sort().map(t=>[t,t])],rosterTag)}</select></label><div class="cards roster-grid">${s.wizards.filter(w=>w.status!=='Deceased'&&(!rosterTag||(w.tags||[]).includes(rosterTag))).map(w=>wizardCard(w)).join('')||empty('There is still room to make a first impression. Recruit at the Front Desk.')}</div>${facilityHeader(id)}`;}
 else if(id==='storage'){html=tabs([['items','Equipment'],['supplies','Supplies'],['vault','Deep storage'],['records','Item records']],tab);if(tab==='items')html+=inventoryContent();else if(tab==='supplies')html+=suppliesContent();else if(tab==='vault'){html+=`<p class="panel-intro">Shelved items retain their full rolls and provenance. Withdraw them to equip. Past discoveries and sold items also remain in this catalogue.</p><div id="archive-list">Opening the catalogue…</div>`;queueMicrotask(()=>loadHistory('items',true));}else html+=`<p class="panel-intro">The greatest rolls in each family. There is no perfect 100% roll and no designed maximum.</p><div class="cards">${Object.entries(s.itemRecords).map(([key,r])=>`<div class="card"><p>${esc(key.replace('_',' · ').toUpperCase())}</p><h3>${fmt(r.value)}</h3><p>${esc(r.name)} · Year ${r.year}</p>${tag(r.quality)}${button('Provenance','item-history',`data-id="${r.id}"`,'secondary small')}</div>`).join('')||empty('The first discovery will start your record book.')}</div>`;}
 else if(id==='training')html=`<div class="club-invite"><div><small>AN ACTIVE CHALLENGE</small><h3>The Dueling Club</h3><p>${clubRank(s)} · ${s.dueling?.cleared?.length||0}/12 challengers defeated</p></div>${button(s.duel&&!s.duel.finished?'Resume live bout':'Enter the club','duel')}</div><p class="panel-intro">Training improves adventure level, HP, mana, and modest casting power. The spells themselves come from equipment. About 160 XP per hour before bonuses.</p>${assignmentPanel(['training','mining','smithing','teaching'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='runes')html=`<p class="panel-intro">Choose a recipe, then select its wizards. Their speeds combine into one shared batch per recipe and tier. One unscribed rune becomes 12 spell charges.</p>${suppliesContent(false)}<div class="actions">${workerButton('blank','Make unscribed runes')}${workerButton('seals','Bind Boss Seals')}</div>${section('Work in this room')}${productionGroups(s,['blank',...FAMILIES.map(f=>f.id),'seals']).map(productionMarkup).join('')||empty('No production assigned. Choose Inscribe beside a rune, or start blanks or seals above.')}${assignmentPanel(['enchanting'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='infirmary')html=`<p class="panel-intro">All wizards slowly recover at home. Infirmary patients regain HP and mana much faster, and injuries heal sooner. No random treatment death.</p><div class="cards">${M.active(s).filter(w=>w.job==='recovery').map(w=>`<div class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>${w.injury?esc(w.injury.name)+' · '+duration(w.injury.until-s.time):'Recovering from expedition'}</p></div></div><div class="actions">${button('Assign bed','assign-recovery',`data-id="${w.id}"`)}${button('Use potion','potion',`data-id="${w.id}"`,'secondary')}</div></div>`).join('')||empty('No patients. This is the preferred outcome.')}</div>${assignmentPanel(['recovery'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='gate')html=gateContent();
 else if(id==='rift')html=riftContent();
 else if(id==='archives'){html=tabs([['records','Record books'],['wizard-history','Wizard archives'],['timeline','Chronicle'],['seasons','Seasons'],['conversations','Conversations']],tab);if(tab==='records')html+=recordsContent();else if(tab==='seasons')html+=`<p class="panel-intro">Every completed year preserves all four leagues, standings, playoffs, movements, rosters, individual statistics, and match IDs.</p><label>Academy Year<input id="season-year" type="number" min="1" max="${Math.max(1,M.year(s)-1)}" value="${Math.max(1,M.year(s)-1)}"></label><div class="actions" style="margin-top:14px">${button('Open season','load-season')}</div>${M.year(s)===1?empty('The first season is still being written.'):''}`;else{const type=tab==='wizard-history'?'wizards':tab==='timeline'?'timeline':'conversations';html+=`<p class="panel-intro">Permanent records, loaded 30 at a time. ${type==='wizards'?'All attendees receive a record. Living careers are available from the Dormitory.':''}</p><div id="archive-list">Opening the archives…</div>`;queueMicrotask(()=>loadHistory(type,true));}}
 else if(id==='hall'){html=tabs([['legends','Hall of Names'],['achievements','Achievements']],tab);if(tab==='achievements')html+=`<div class="cards">${ACHIEVEMENTS.map(([id,name,desc,key,target,p])=>`<article class="card achievement ${s.achievements.includes(id)?'':'unearned'}"><span class="medal">${s.achievements.includes(id)?'✦':'◇'}</span><div><h3>${esc(name)}</h3><p>${esc(desc)}</p><small>${n(Math.min(s.stats[key]||0,target))} / ${n(target)} · ${p} Prestige</small></div></article>`).join('')}</div>`;else html+=`<p class="panel-intro">A wizard qualifies through 30 floors, 10 boss kills, 500 Rift goals, three championships, 10,000 runes, 30 years of service, or 5,000 healing. Induction is a one-time honor, never an endlessly stacking power bonus.</p><div class="cards">${s.wizards.filter(qualifies).map(w=>`<div class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>${w.hof?'Inscribed in the Hall of Names':'Eligible for induction'}</p></div></div>${button(w.hof?'Read their story':'Induct into the Hall',w.hof?'wizard':'induct',`data-id="${w.id}"`)}</div>`).join('')||empty('Legends take time. The archive is already keeping watch.')}</div>${section('The names we keep')}<div id="archive-list">Opening the memorial register…</div>${facilityHeader(id)}`;if(tab==='legends')queueMicrotask(()=>loadHistory('honors',true));}
 else if(id==='garden')html=`<p class="panel-intro">Brew a restorative potion for 6 gold. Potions restore 45% HP and 30% mana between floors. Baseline brewing takes seven minutes.</p>${assignmentPanel(['garden','foraging','woodcutting','alchemy','cooking'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='observatory')html=`<p class="panel-intro">Trade 3 unscribed runes and fifteen minutes of research for 0.25 Prestige. A slow, dependable reputation beyond dungeon and sport.</p>${assignmentPanel(['research'])}${facultyPanel(id)}${facilityHeader(id)}`;
 panel(r.name,r.sub,html);}
function qualifies(w){return w.hof||(w.stats.depth||0)>=30||(w.stats.bossKills||0)>=10||(w.stats.goals||0)>=500||(w.stats.championships||0)>=3||(w.stats.runes||0)>=10000||(w.stats.healing||0)>=5000||(w.departure?w.departure.year-(Math.floor(w.joined/DAY)+1):(s.time-w.joined)/DAY)>=30;}
function guide(){return `${button('Open tutorial missions','tutorial','','secondary')}<br><div class="cards">${[['A first week in one day','Recruit five wizards. Open the Practice Hall, Rune Chamber, and Rift facility. Train one or two, make blank runes with another, and field a sports lineup. Start on floor 1 with three healthy wizards. Magic Missile works without gear or runes.'],['Builds live in the chest','Every wizard has a focus, robe, and charm. Each item grants its family’s spell. Mix families to create hybrids. Supply matching rune charges; tier II spells need tier II charges. If charges or mana run out, Magic Missile remains available.'],['Decide how greedy to be','Each new floor stops after victory. HP and mana carry forward. Use potions between floors, advance deliberately, or return. A wizard at zero HP dies permanently. Lost equipment stays at that floor until recovered.'],['The Enchanted Forest','Open the Forest from the dungeon gate. Assign a wizard and watch their battle in the live arena. Forest defeats trigger a paid rescue, never ordinary combat death. Materials go to a personal backpack first; transfer them to the Strongroom after returning. Configure retreat, potions and inventory rules on each wizard profile.'],['A school, not a waiting room','Training, rune manufacture, inscription, seal binding, potion brewing, clerical work, and research all progress while away. Farming uses real combat and can kill a weak party. Only assign it after preparing carefully.'],['The sport of Arcane Rift','Two Strikers propel a mote through a shifting aperture, a Controller creates passing lanes, and two Wardens defend. Risky passes can create two-point goals or turnovers. Safe passing reduces turnovers. Fast tempo creates more possessions. Defense and offense trade scoring against protection.'],['The annual calendar','Sixteen match windows fit into a 24-hour Academy Year: fourteen regular games, semifinals, and a final. Top four qualify. The playoff champion goes up; only last place goes down. A tied match uses sudden aperture. Five healthy configured starters or bench substitutes are required.'],['Generations matter','New applicants arrive every year. Wizards retire around 60 and may teach until natural death around 85. The original staff may be inherited by several generations. Archives retain each career; Hall of Fame induction grants one-time Prestige.'],['Time, safety, and saves','Up to twelve hours of absence progress on return. Beyond that, the academy calendar pauses too. New-floor combat pauses when hidden and resumes when visible. Local saves use IndexedDB; cloud saves use revision-checked transactions. There is no shared player marketplace or anti-cheat server.'],['Coping with catastrophe','Applicants remain for three years. Recruitment is free. Below five active wizards, Emergency Admissions restores your roster to five instantly and free. These level-1 recruits have modest stats and no equipment. Equipment can be recovered through a paid service or by clearing its loss floor. No gold is needed to recruit.'],['Reading an item roll','Typical rolls cluster near their expected value, but exceptional and anomalous outliers are possible at any rarity. The quality label describes the power roll. HP, mana, and defense roll independently. Compare actual statistics; rarity alone is not enough.']].map(([h,p])=>`<div class="card"><h3>${h}</h3><p style="margin-top:10px">${p}</p></div>`).join('')}</div>`;}
function inventoryContent(){let rows=s.items.filter(i=>(!inventory.family||i.family===inventory.family)&&(inventory.rarity===''||i.rarity===Number(inventory.rarity))&&(!inventory.slot||i.slot===inventory.slot)&&(!inventory.owner||(inventory.owner==='equipped'?i.owner:!i.owner))&&(!inventory.search||i.name.toLowerCase().includes(inventory.search.toLowerCase())));rows.sort((a,b)=>inventory.sort==='name'?a.name.localeCompare(b.name):b[inventory.sort]-a[inventory.sort]);const total=rows.length;rows=rows.slice(inventory.page*20,inventory.page*20+20);return `<p class="panel-intro">Equipment is found below the academy. Its spells define the wizard. Every roll is unique; lower rarities can still be extraordinary. Above 180 active items, unequipped items are safely shelved in Deep Storage.</p><div class="filters"><label>Family<select data-change="inventory" data-key="family">${options([['','All families'],...FAMILIES.map(f=>[f.id,f.name])],inventory.family)}</select></label><label>Rarity<select data-change="inventory" data-key="rarity">${options([['','All rarities'],...RARITIES.map((r,i)=>[i,r])],inventory.rarity)}</select></label><label>Slot<select data-change="inventory" data-key="slot">${options([['','All slots'],['focus','Focus'],['robe','Robe'],['charm','Charm']],inventory.slot)}</select></label><label>Status<select data-change="inventory" data-key="owner">${options([['','All items'],['equipped','Equipped'],['free','Unequipped']],inventory.owner)}</select></label><label>Sort<select data-change="inventory" data-key="sort">${options([['power','Power'],['hp','HP'],['mana','Mana'],['defense','Defense'],['rarity','Rarity'],['floor','Depth'],['name','Name']],inventory.sort)}</select></label><label>Search<input id="item-search" value="${esc(inventory.search)}" placeholder="Item name"></label></div><div class="inventory-grid">${rows.map(i=>itemTile(i)).join('')||empty('No equipment matches. Most equipment comes from dungeon discoveries, especially bosses.')}</div><div class="pagination">${inventory.page?button('Previous','item-page','data-dir="-1"','secondary'):''}<span class="fineprint">${total} items · page ${inventory.page+1}</span>${(inventory.page+1)*20<total?button('Next','item-page','data-dir="1"','secondary'):''}</div>`;}
function itemTile(i){const f=family(i.family),owner=i.owner?s.wizards.find(w=>w.id===i.owner)?.name||'an archived wizard':null;return `<button class="item-tile" data-act="item" data-id="${i.id}" data-inventory="1" style="--item-rarity:${RARITY_COLORS[i.rarity]};--item-family:${f.color}" aria-label="${esc(i.name)}, ${RARITIES[i.rarity]}, ${i.slot}, ${fmt(i.power)} power${owner?', equipped by '+esc(owner):''}${i.locked?', locked':''}. Tap for details and comparison."><span class="tile-top"><span class="tile-glyph" aria-hidden="true">${f.icon}</span><span class="tile-flags">${i.locked?'♢ ':''}${i.owner?'E':''}</span></span><strong class="tile-name">${esc(i.name)}</strong><span class="tile-meta">${RARITIES[i.rarity]} · ${i.slot}</span><span class="tile-bottom"><b>${fmt(i.power)} <small>power</small></b><small>F${i.floor}</small></span></button>`;}
