function renderItem(){const i=route.item||s.items.find(i=>i.id===route.id);if(!i){panel('Missing item','Strongroom',empty('That item is not in active storage. Check Deep Storage or lost caches.'));return;}const f=family(i.family);let html=`<div class="actions inventory-back">${route.slotParent?button('← Back to slot comparison','slot-return','','secondary'):button('← Back to Strongroom','inventory-back','','secondary')}</div>`+itemCard(i);html+=section('Granted magic')+`<p>${esc(f.spell)} · ${f.kind==='heal'?'Heals the most injured ally and cleanses poison and curse.':f.kind==='shield'?'Shields the most vulnerable ally and draws enemy attacks.':f.kind==='summon'?'Raises a fighting custodian that absorbs attacks.':f.kind==='aoe'?'Hits every enemy and applies '+f.status+'.':'Strikes an enemy and applies '+f.status+'.'}</p><div class="note">Consumes ${i.charges} ${f.name} tier ${i.tier} rune charges per cast. Mana persists between floors. This item has an uncapped probability-distributed power roll of ${i.roll.toFixed(3)}× its rarity and depth baseline.</div>${i.affixes.map(a=>`<p class="affix"><strong>${AFFIXES.find(x=>x.id===a)?.name}</strong> · ${AFFIXES.find(x=>x.id===a)?.desc}</p>`).join('')}`;
 const available=s.items.some(x=>x.id===i.id);if(available){html+=section('Compare & equip')+`<label>Wizard<select id="equip-target">${options([['','Choose a wizard'],...M.active(s).map(w=>[w.id,w.name])],route.target||i.owner||'')}</select></label><div id="item-comparison">${comparison(i,route.target||i.owner)}</div><div class="actions" style="margin-top:15px">${button('Equip to selected wizard','equip-item',`data-id="${i.id}"`)}${button(i.locked?'Unlock item':'Lock item','lock-item',`data-id="${i.id}"`,'secondary')}${!i.owner&&!i.carriedBy?button('Shelve safely','vault-item',`data-id="${i.id}"`,'secondary'):''}${!i.locked&&!i.owner&&!i.carriedBy?button('Sell · '+n(i.value)+' gold','sell-item',`data-id="${i.id}"`,'danger'):''}</div>`;}html+=section('Provenance')+`<p class="fineprint">Found in year ${i.found.year} · Floor ${i.found.floor}${i.found.boss?' · '+esc(i.found.boss):''}<br>Discovered by ${esc(i.found.wizard)}<br>Original rarity: ${RARITIES[i.rarity]} · ${esc(i.id)}${i.carriedBy?'<br>Carried by '+esc(s.wizards.find(w=>w.id===i.carriedBy)?.name||'an adventurer'):''}</p><div class="chips">${i.owners.map(o=>tag(o.name+' · Y'+o.year+(o.until?'–'+o.until:''))).join('')||tag('No previous owners')}</div>${i.legacy?`<div class="metrics">${metric('Creatures defeated',n(i.legacy.kills||0))}${metric('Forest victories',n(i.legacy.forestKills||0))}${metric('Deepest floor',n(i.legacy.deepest||0))}${metric('Bosses',n(i.legacy.bosses||0))}${metric('Rift titles',n(i.legacy.riftTitles||0))}</div>`:''}`;panel(i.name,'Equipment · '+f.name,html);}
function comparison(i,id){const w=s.wizards.find(w=>w.id===id);if(!w)return '';const old=s.items.find(x=>x.id===w.equipment[i.slot]);return `<div class="note">${old?'Replacing '+esc(old.name):'Empty '+i.slot+' slot'}<div class="metrics">${['power','hp','mana','defense'].map(k=>metric(k,`${i[k]-(old?.[k]||0)>=0?'+':''}${fmt(i[k]-(old?.[k]||0))}`)).join('')}</div></div>`;}
