 if(candidate){const comp=compareLoadout(s,w,candidate),available=!candidate.owner||candidate.owner===w.id,selected=current?.id===candidate.id;const spell=i=>i?`${family(i.family).spell} · Tier ${i.tier} · ${i.charges} charges/cast`:'No equipment spell; Magic Missile remains available.';const affixes=i=>i?.affixes.length?i.affixes.map(id=>{const a=AFFIXES.find(x=>x.id===id);return `<p><strong>${esc(a?.name||id)}</strong> · ${esc(a?.desc||'')}</p>`;}).join(''):'<p>No affixes.</p>';html+=`<div class="equipment-compare"><div><small>CURRENT ${route.slot.toUpperCase()}</small><h3>${esc(current?.name||'Empty slot')}</h3><p>${spell(current)}</p>${affixes(current)}</div><div><small>${selected?'CURRENT ITEM':'SELECTED ITEM'} · ${RARITIES[candidate.rarity]}</small><h3>${esc(candidate.name)}</h3><p>${spell(candidate)}</p>${affixes(candidate)}</div></div><div class="table-wrap"><table><thead><tr><th>Item stat</th><th>Current</th><th>Selected</th><th>Change</th></tr></thead><tbody>${['power','hp','mana','defense'].map(k=>{const d=candidate[k]-(current?.[k]||0);return `<tr><td>${k}</td><td>${fmt(current?.[k]||0)}</td><td>${fmt(candidate[k])}</td><td class="${d>0?'stat-gain':d<0?'stat-loss':''}">${d>0?'+':''}${fmt(d)}</td></tr>`;}).join('')}</tbody></table></div><p class="fineprint">Whole-wizard totals after traits, injury, and affixes:</p><div class="metrics">${['power','hp','mana','defense'].map(k=>metric(k,fmt(comp.before[k])+' → '+fmt(comp.after[k]))).join('')}</div><div class="actions">${button(selected?'Already equipped':available?'Equip to '+esc(w.name):'Carried by '+esc(s.wizards.find(x=>x.id===candidate.owner)?.name||'another wizard'),'slot-equip',`data-id="${candidate.id}" ${!canEdit||!available||selected?'disabled':''}`)}${button('Full item details','slot-details',`data-id="${candidate.id}"`,'secondary')}</div>`;}
 else html+=`<div class="note"><strong>Currently equipped: ${esc(current?.name||'Nothing')}</strong><p>Choose an item to see its spell, affixes, stat differences, and your wizard’s resulting totals.</p>${current?button('Unequip current item','slot-unequip',canEdit?'':'disabled','secondary'):''}</div>`;
