window.addEventListener('pagehide',()=>{if(s)P.saveLocal(s).catch(()=>{});});
async function boot(){startPWA(()=>{if(route?.type==='install')renderInstall();});startAudio(()=>({s,route}));try{await P.openDB();startScene(()=>s);startRiftBroadcast(()=>route?.type==='match'?{match:route.match,watch,motion:s?.settings.motion}:null);startCombatArena(()=>route?.type==='forest'&&s?.forestBattles?.[route.watch]?{combat:s.forestBattles[route.watch],wizards:s.wizards,settings:s.settings}:route?.type==='combat'?s:route?.type==='duel'&&s?.duel&&(route.bout||!s.duel.finished)?s.duel.run:null);if(localStorage.getItem('wa-mode')==='local')await enterAccount('local');else if(localStorage.getItem('wa-mode')==='cloud'){await P.connect();if(P.authUser)await enterAccount(P.authUser.uid);else authScreen();}else authScreen();}catch(e){authScreen();$('auth-status').textContent=errorMessage(e);}}

function renderInstall(){const status=installStatus();panel('Install Wizard Academy','Your academy on the home screen',`<p class="panel-intro">${status.standalone?'You are running the installed app.':'Install an academy icon that opens in its own app window.'}</p>${!status.standalone?button('Install app','install-app','','gold'):''}<div class="note"><strong>Samsung / Android</strong><p>Tap Install app when available, or use your browser menu → Install app / Add to Home screen.</p><strong>iPad</strong><p>Open this site in Safari → Share → Add to Home Screen. Leave Open as Web App enabled if shown, then tap Add.</p></div><p>${esc(status.message)}</p><p class="fineprint">Open online once to cache the game. Local play can then open offline; cloud sign-in and synchronization require a connection. Cloud users should save before installing and sign into the same account. For local play, export a backup first: some installed browsers use separate storage. Restore it from Front Desk → Settings & save if needed.</p>${status.update?button('Save & reload update','app-update'):''}<p class="fineprint">Updates wait until you reload them or close all academy windows. Installation does not change the 12-hour offline progression cap.</p>`);}

boot();
